#!/usr/bin/env bash
# AI Usage Note
# Generated by Claude (Claude Code)
# How it was verified: ran a first deploy, an update, a deploy of an unpublished commit, a manual rollback
# and an automatic rollback from a broken image against a local checkout and registry.
# Reviewed by: Viktoriia Baran
set -euo pipefail

compose=(docker compose -f docker-compose.staging.yml)

# Starts API_VERSION and waits until the API is healthy.
start() {
  "${compose[@]}" up -d --remove-orphans || return 1
  local api
  api=$("${compose[@]}" ps -q api)
  for _ in $(seq 60); do
    if [[ "$(docker inspect -f '{{.State.Health.Status}}' "$api")" = healthy ]]; then
      return 0
    fi
    sleep 2
  done
  return 1
}

# On every exit: the checkout goes back to the version that is still running, if the deploy did not get
# that far, then the registry login and the lock go.
restore=''
# shellcheck disable=SC2317 # runs from the EXIT trap
cleanup() {
  if [[ -n "$restore" ]]; then
    git checkout --quiet --detach "$restore"
  fi
  if [[ -n "${GHCR_USER:-}" ]]; then
    docker logout ghcr.io >/dev/null
  fi
  rmdir /tmp/nearby-staging-deploy.lock
}

# The checkout below replaces this file, so bash has to read all of it first: everything runs in main.
main() {
  cd "$(dirname "$0")/.."

  local lock=/tmp/nearby-staging-deploy.lock
  if ! mkdir "$lock" 2>/dev/null; then
    echo "Another deploy is running; if not, remove $lock" >&2
    exit 1
  fi
  trap cleanup EXIT

  # The image is private: CI passes its user in GHCR_USER and a token valid for the job on stdin.
  if [[ -n "${GHCR_USER:-}" ]]; then
    docker login ghcr.io -u "$GHCR_USER" --password-stdin >/dev/null
  fi

  # CI builds the image for linux/amd64 only.
  local arch
  arch=$(docker info --format '{{.Architecture}}')
  if [[ "$arch" != x86_64 ]]; then
    echo "The server is $arch, but the image is built for x86_64: use an x86 server" >&2
    exit 1
  fi

  git fetch --quiet origin staging
  local input=${1:-origin/staging} version
  version=$(git rev-parse --verify --quiet --end-of-options "$input^{commit}") || true
  if [[ -z "$version" ]] || ! git merge-base --is-ancestor "$version" origin/staging ||
    ! git cat-file -e "$version:docker-compose.staging.yml" 2>/dev/null; then
    echo "$input is not a commit on staging with the staging setup" >&2
    exit 1
  fi

  # The version running now, to roll back to: its image tag is its commit.
  local running previous=''
  running=$("${compose[@]}" ps -q api)
  if [[ -n "$running" ]]; then
    previous=$(docker inspect -f '{{.Config.Image}}' "$running" | sed 's/.*://')
  fi

  echo "Deploying $version"
  git checkout --quiet --detach "$version"
  restore=$previous
  docker volume create nearby-staging-db >/dev/null
  docker volume create nearby-staging-caddy >/dev/null

  export API_VERSION=$version
  if ! "${compose[@]}" pull --quiet; then
    echo "Cannot pull $version: CI has not published it yet, or ghcr.io is not logged in" >&2
    exit 1
  fi
  # Keys are created once and kept: generate-keys never overwrites a file. The API runs as node.
  "${compose[@]}" run --rm --no-deps --user root -v "$PWD/keys:/app/keys" migrate \
    sh -c 'node dist/scripts/generate-keys.js && chown -R node:node keys'

  if [[ -n "$("${compose[@]}" ps -q backup)" ]]; then
    "${compose[@]}" exec -T backup sh /backup-db.sh now
  fi

  # On its own first: `up` replaces the API before migrate runs, so a failed migration there would take the
  # running version down with it.
  if ! "${compose[@]}" run --rm migrate; then
    echo "The migrations of $version failed; ${previous:-nothing} is still running. Before the next deploy," \
      "resolve the failed migration: \"A migration failed\" in docs/operations/staging.md" >&2
    exit 1
  fi

  if start; then
    restore=''
    echo "$(date -u +%FT%TZ) $version" >>deploy.log
    docker image prune --all --force --filter until=168h >/dev/null || echo "Removing old images failed" >&2
    echo "Deployed $version"
    exit 0
  fi

  echo "$version is not healthy: ${compose[*]} logs api migrate" >&2
  if [[ -n "$previous" && "$previous" != "$version" ]]; then
    git checkout --quiet --detach "$previous"
    restore=''
    export API_VERSION=$previous
    if start; then
      echo "$(date -u +%FT%TZ) $previous (rolled back from $version)" >>deploy.log
      echo "Rolled back to $previous" >&2
    else
      echo "Rolling back to $previous failed too" >&2
    fi
  fi
  exit 1
}

# On one line with main, so bash never reads on into the file the checkout put here.
# shellcheck disable=SC2317
{ main "$@"; exit; }
